insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends', 'In chemistry, periodic trends are specific patterns present in the periodic table that illustrate different aspects of certain elements when grouped by period and/or group. They were discovered by the Russian chemist Dmitri Mendeleev in 1863. Major periodic trends include atomic radius, ionization energy, electron affinity, electronegativity, nucleophilicity, electrophilicity, valency, nuclear charge, and metallic character. Mendeleev built the foundation of the periodic table. Mendeleev organized the elements based on atomic weight, leaving empty spaces where he believed undiscovered elements would take their places. Mendeleev''s discovery of this trend allowed him to predict the existence and properties of three unknown elements, which were later discovered by other chemists and named gallium, scandium, and germanium. English physicist Henry Moseley discovered that organizing the elements by atomic number instead of atomic weight would naturally group elements with similar properties.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In chemistry, periodic trends are specific patterns present in the periodic table that illustrate different aspects of certain elements when grouped by period and/or group. They were discovered by the Russian chemist Dmitri Mendeleev in 1863. Major periodic trends include atomic radius, ionization energy, electron affinity, electronegativity, nucleophilicity, electrophilicity, valency, nuclear charge, and metallic character. Mendeleev built the foundation of the periodic table. Mendeleev organized the elements based on atomic weight, leaving empty spaces where he believed undiscovered elements would take their places. Mendeleev''s discovery of this trend allowed him to predict the existence and properties of three unknown elements, which were later discovered by other chemists and named gallium, scandium, and germanium. English physicist Henry Moseley discovered that organizing the elements by atomic number instead of atomic weight would naturally group elements with similar properties.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Atomic radius', 'The atomic radius is the distance from the atomic nucleus to the outermost electron orbital in an atom. In general, the atomic radius decreases as we move from left-to-right in a period, and it increases when we go down a group. This is because in periods, the valence electrons are in the same outermost shell. The atomic number increases within the same period while moving from left to right, which in turn increases the effective nuclear charge. The increase in attractive forces reduces the atomic radius of elements. When we move down the group, the atomic radius increases due to the addition of a new shell.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The atomic radius is the distance from the atomic nucleus to the outermost electron orbital in an atom. In general, the atomic radius decreases as we move from left-to-right in a period, and it increases when we go down a group. This is because in periods, the valence electrons are in the same outermost shell. The atomic number increases within the same period while moving from left to right, which in turn increases the effective nuclear charge. The increase in attractive forces reduces the atomic radius of elements. When we move down the group, the atomic radius increases due to the addition of a new shell.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Nuclear charge and effective nuclear charge', 'Nuclear charge is defined as the number of protons in the nucleus of an element. Thus, from left-to-right of a period and top-to-bottom of a group, as the number of protons in the nucleus increases, the nuclear charge will also increase. However, electrons of multi-electron atoms do not experience the entire nuclear charge due to shielding effects from the other electrons. In this case, the nuclear charge of atoms that experience this shielding is referred to as effective nuclear charge. Shielding increases as the number of an atom''s inner shells increases. So from left-to-right of a period, the effective nuclear charge will still increase. But, from top-to-bottom of a group, as the number of shells increases, the effective nuclear charge will decrease.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Nuclear charge is defined as the number of protons in the nucleus of an element. Thus, from left-to-right of a period and top-to-bottom of a group, as the number of protons in the nucleus increases, the nuclear charge will also increase. However, electrons of multi-electron atoms do not experience the entire nuclear charge due to shielding effects from the other electrons. In this case, the nuclear charge of atoms that experience this shielding is referred to as effective nuclear charge. Shielding increases as the number of an atom''s inner shells increases. So from left-to-right of a period, the effective nuclear charge will still increase. But, from top-to-bottom of a group, as the number of shells increases, the effective nuclear charge will decrease.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Ionization energy', 'The ionization energy is the minimum amount of energy that an electron in a gaseous atom or ion has to absorb to come out of the influence of the attracting force of the nucleus. It is also referred to as ionization potential. The first ionization energy is the amount of energy that is required to remove the first electron from a neutral atom. The energy needed to remove the second electron from the neutral atom is called the second ionization energy and so on. As one moves from left-to-right across a period in the modern periodic table, the ionization energy increases as the nuclear charge increases and the atomic size decreases. The decrease in the atomic size results in a more potent force of attraction between the electrons and the nucleus. However, suppose one moves down in a group. In that case, the ionization energy decreases as atomic size increases due to adding a valence shell, thereby diminishing the nucleus''s attraction to electrons.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The ionization energy is the minimum amount of energy that an electron in a gaseous atom or ion has to absorb to come out of the influence of the attracting force of the nucleus. It is also referred to as ionization potential. The first ionization energy is the amount of energy that is required to remove the first electron from a neutral atom. The energy needed to remove the second electron from the neutral atom is called the second ionization energy and so on. As one moves from left-to-right across a period in the modern periodic table, the ionization energy increases as the nuclear charge increases and the atomic size decreases. The decrease in the atomic size results in a more potent force of attraction between the electrons and the nucleus. However, suppose one moves down in a group. In that case, the ionization energy decreases as atomic size increases due to adding a valence shell, thereby diminishing the nucleus''s attraction to electrons.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Electron affinity', 'The energy released when an electron is added to a neutral gaseous atom to form an anion is known as electron affinity. Trend-wise, as one progresses from left to right across a period, the electron affinity will increase as the nuclear charge increases and the atomic size decreases resulting in a more potent force of attraction of the nucleus and the added electron. However, as one moves down in a group, electron affinity decreases because atomic size increases due to the addition of a valence shell, thereby weakening the nucleus''s attraction to electrons. Although it may seem that fluorine should have the greatest electron affinity, its small size generates enough repulsion among the electrons, resulting in chlorine having the highest electron affinity in the halogen family.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The energy released when an electron is added to a neutral gaseous atom to form an anion is known as electron affinity. Trend-wise, as one progresses from left to right across a period, the electron affinity will increase as the nuclear charge increases and the atomic size decreases resulting in a more potent force of attraction of the nucleus and the added electron. However, as one moves down in a group, electron affinity decreases because atomic size increases due to the addition of a valence shell, thereby weakening the nucleus''s attraction to electrons. Although it may seem that fluorine should have the greatest electron affinity, its small size generates enough repulsion among the electrons, resulting in chlorine having the highest electron affinity in the halogen family.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Electronegativity', 'The tendency of an atom in a molecule to attract the shared pair of electrons towards itself is known as electronegativity. It is a dimensionless quantity because it is only a tendency. The most commonly used scale to measure electronegativity was designed by Linus Pauling. The scale has been named the Pauling scale in his honour. According to this scale, fluorine is the most electronegative element, while cesium is the least electronegative element. Trend-wise, as one moves from left to right across a period in the modern periodic table, the electronegativity increases as the nuclear charge increases and the atomic size decreases. However, if one moves down in a group, the electronegativity decreases as atomic size increases due to the addition of a valence shell, thereby decreasing the atom''s attraction to electrons. However, in group XIII (boron family), the electronegativity first decreases from boron to aluminium and then increases down the group. It is due to the fact that the atomic size increases as we move down the group, but at the same time the effective nuclear charge increases due to poor shielding of the inner d and f electrons. As a result, the force of attraction of the nucleus for the electrons increases and hence the electronegativity increases from aluminium to thallium.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The tendency of an atom in a molecule to attract the shared pair of electrons towards itself is known as electronegativity. It is a dimensionless quantity because it is only a tendency. The most commonly used scale to measure electronegativity was designed by Linus Pauling. The scale has been named the Pauling scale in his honour. According to this scale, fluorine is the most electronegative element, while cesium is the least electronegative element. Trend-wise, as one moves from left to right across a period in the modern periodic table, the electronegativity increases as the nuclear charge increases and the atomic size decreases. However, if one moves down in a group, the electronegativity decreases as atomic size increases due to the addition of a valence shell, thereby decreasing the atom''s attraction to electrons. However, in group XIII (boron family), the electronegativity first decreases from boron to aluminium and then increases down the group. It is due to the fact that the atomic size increases as we move down the group, but at the same time the effective nuclear charge increases due to poor shielding of the inner d and f electrons. As a result, the force of attraction of the nucleus for the electrons increases and hence the electronegativity increases from aluminium to thallium.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Valency', 'The valency of an element is the number of electrons that must be lost or gained by an atom to obtain a stable electron configuration. In simple terms, it is the measure of the combining capacity of an element to form chemical compounds. Electrons found in the outermost shell are generally known as valence electrons; the number of valence electrons determines the valency of an atom. Trend-wise, while moving from left to right across a period, the number of valence electrons of elements increases and varies between one and eight. But the valency of elements first increases from 1 to 4, and then it decreases to 0 as we reach the noble gases. However, as we move down in a group, the number of valence electrons generally does not change. Hence, in many cases the elements of a particular group have the same valency. However, this periodic trend is not always followed for heavier elements, especially for the f-block and the transition metals. These elements show variable valency as these elements have a d-orbital as the penultimate orbital and an s-orbital as the outermost orbital. The energies of these (n-1)d and ns orbitals (e.g., 4d and 5s) are relatively close.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The valency of an element is the number of electrons that must be lost or gained by an atom to obtain a stable electron configuration. In simple terms, it is the measure of the combining capacity of an element to form chemical compounds. Electrons found in the outermost shell are generally known as valence electrons; the number of valence electrons determines the valency of an atom. Trend-wise, while moving from left to right across a period, the number of valence electrons of elements increases and varies between one and eight. But the valency of elements first increases from 1 to 4, and then it decreases to 0 as we reach the noble gases. However, as we move down in a group, the number of valence electrons generally does not change. Hence, in many cases the elements of a particular group have the same valency. However, this periodic trend is not always followed for heavier elements, especially for the f-block and the transition metals. These elements show variable valency as these elements have a d-orbital as the penultimate orbital and an s-orbital as the outermost orbital. The energies of these (n-1)d and ns orbitals (e.g., 4d and 5s) are relatively close.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Periodic trends: Metallic and non-metallic properties', 'Metallic properties generally increase down the groups, as decreasing attraction between the nuclei and outermost electrons causes these electrons to be more loosely bound and thus able to conduct heat and electricity. Across each period, from left to right, the increasing attraction between the nuclei and the outermost electrons causes the metallic character to decrease. In contrast, the nonmetallic character decreases down the groups and increases across the periods.', 'Wikipedia: Periodic trends', 'https://en.wikipedia.org/w/index.php?title=Periodic_trends&oldid=1379205355', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Metallic properties generally increase down the groups, as decreasing attraction between the nuclei and outermost electrons causes these electrons to be more loosely bound and thus able to conduct heat and electricity. Across each period, from left to right, the increasing attraction between the nuclei and the outermost electrons causes the metallic character to decrease. In contrast, the nonmetallic character decreases down the groups and increases across the periods.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity', 'Electronegativity, symbolized as χ, is the tendency for an atom of a given chemical element to attract shared electrons (or electron density) when forming a chemical bond. An atom''s electronegativity is affected by both its atomic number and the distance at which its valence electrons reside from the charged nucleus. The higher the associated electronegativity, the more an atom or a substituent group attracts electrons. Electronegativity serves as a simple way to quantitatively estimate the bond energy, and the sign and magnitude of a bond''s chemical polarity, which characterizes a bond along the continuous scale from covalent to ionic bonding. The loosely defined term electropositivity is the opposite of electronegativity: it characterizes an element''s tendency to donate valence electrons. On the most basic level, electronegativity is determined by factors like the nuclear charge (the more protons an atom has, the more "pull" it will have on electrons) and the number and location of other electrons in the electron shells (the more electrons an atom has, the farther from the nucleus the valence electrons will be, and as a result, the less positive charge they will experience—both because of their increased distance from the nucleus and because the other electrons in the lower energy core orbitals will act to shield the valence electrons from the positively charged nucleus).', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Electronegativity, symbolized as χ, is the tendency for an atom of a given chemical element to attract shared electrons (or electron density) when forming a chemical bond. An atom''s electronegativity is affected by both its atomic number and the distance at which its valence electrons reside from the charged nucleus. The higher the associated electronegativity, the more an atom or a substituent group attracts electrons. Electronegativity serves as a simple way to quantitatively estimate the bond energy, and the sign and magnitude of a bond''s chemical polarity, which characterizes a bond along the continuous scale from covalent to ionic bonding. The loosely defined term electropositivity is the opposite of electronegativity: it characterizes an element''s tendency to donate valence electrons. On the most basic level, electronegativity is determined by factors like the nuclear charge (the more protons an atom has, the more "pull" it will have on electrons) and the number and location of other electrons in the electron shells (the more electrons an atom has, the farther from the nucleus the valence electrons will be, and as a result, the less positive charge they will experience—both because of their increased distance from the nucleus and because the other electrons in the lower energy core orbitals will act to shield the valence electrons from the positively charged nucleus).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity', 'though the concept was known before that and was studied by many chemists including Avogadro. Despite its long history, an accurate scale of electronegativity was not developed until 1932, when Linus Pauling proposed an electronegativity scale that depends on bond energies, as a development of valence bond theory. It has been shown to correlate with several other chemical properties. Electronegativity cannot be directly measured and must be calculated from other atomic or molecular properties. Several methods of calculation have been proposed, and although there may be small differences in the numerical values of electronegativity, all methods show the same periodic trends between elements. The most commonly used method of calculation is that originally proposed by Linus Pauling. This gives a dimensionless quantity, commonly referred to as the Pauling scale (χr), on a relative scale running from 0.79 to 3.98 (hydrogen = 2.20). When other methods of calculation are used, it is conventional (although not obligatory) to quote the results on a scale that covers the same range of numerical values: this is known as electronegativity in Pauling units.', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'though the concept was known before that and was studied by many chemists including Avogadro. Despite its long history, an accurate scale of electronegativity was not developed until 1932, when Linus Pauling proposed an electronegativity scale that depends on bond energies, as a development of valence bond theory. It has been shown to correlate with several other chemical properties. Electronegativity cannot be directly measured and must be calculated from other atomic or molecular properties. Several methods of calculation have been proposed, and although there may be small differences in the numerical values of electronegativity, all methods show the same periodic trends between elements. The most commonly used method of calculation is that originally proposed by Linus Pauling. This gives a dimensionless quantity, commonly referred to as the Pauling scale (χr), on a relative scale running from 0.79 to 3.98 (hydrogen = 2.20). When other methods of calculation are used, it is conventional (although not obligatory) to quote the results on a scale that covers the same range of numerical values: this is known as electronegativity in Pauling units.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity', 'As it is usually calculated, electronegativity is not a property of an atom alone, but rather a property of an atom in a molecule. Even so, the electronegativity of an atom is strongly correlated with the first ionization energy. The electronegativity is slightly negatively correlated (for smaller electronegativity values) and rather strongly positively correlated (for most and larger electronegativity values) with the electron affinity. It is to be expected that the electronegativity of an element will vary with its chemical environment, but it is usually considered to be a transferable property, that is to say, that similar values will be valid in a variety of situations. By Pauling scale, caesium is the least electronegative element (0.79); fluorine is the most (3.98).', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'As it is usually calculated, electronegativity is not a property of an atom alone, but rather a property of an atom in a molecule. Even so, the electronegativity of an atom is strongly correlated with the first ionization energy. The electronegativity is slightly negatively correlated (for smaller electronegativity values) and rather strongly positively correlated (for most and larger electronegativity values) with the electron affinity. It is to be expected that the electronegativity of an element will vary with its chemical environment, but it is usually considered to be a transferable property, that is to say, that similar values will be valid in a variety of situations. By Pauling scale, caesium is the least electronegative element (0.79); fluorine is the most (3.98).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity: Pauling electronegativity', 'Pauling first proposed the concept of electronegativity in 1932 to explain why the covalent bond between two different atoms (A–B) is stronger than the average of the A–A and the B–B bonds. According to valence bond theory, of which Pauling was a notable proponent, this "additional stabilization" of the heteronuclear bond is due to the contribution of ionic canonical forms to the bonding. The difference in electronegativity between atoms A and B is given by: where the dissociation energies, Ed, of the A–B, A–A and B–B bonds are expressed in electronvolts, the factor (eV)−1⁄2 being included to ensure a dimensionless result. Hence, the difference in Pauling electronegativity between hydrogen and bromine is 0.73 (dissociation energies: H–Br, 3.79 eV; H–H, 4.52 eV; Br–Br 2.00 eV)', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Pauling first proposed the concept of electronegativity in 1932 to explain why the covalent bond between two different atoms (A–B) is stronger than the average of the A–A and the B–B bonds. According to valence bond theory, of which Pauling was a notable proponent, this "additional stabilization" of the heteronuclear bond is due to the contribution of ionic canonical forms to the bonding. The difference in electronegativity between atoms A and B is given by: where the dissociation energies, Ed, of the A–B, A–A and B–B bonds are expressed in electronvolts, the factor (eV)−1⁄2 being included to ensure a dimensionless result. Hence, the difference in Pauling electronegativity between hydrogen and bromine is 0.73 (dissociation energies: H–Br, 3.79 eV; H–H, 4.52 eV; Br–Br 2.00 eV)');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity: Pauling electronegativity', 'As only differences in electronegativity are defined, it is necessary to choose an arbitrary reference point to construct a scale. Hydrogen was chosen as the reference, as it forms covalent bonds with a large variety of elements: its electronegativity was fixed first at 0, then in his famous book at 2.1 to avoid negative electronegativity figures, later revised to 2.20 by Allred. It is also necessary to decide which of the two elements is the more electronegative (equivalent to choosing one of the two possible signs for the square root). This is usually done using "chemical intuition": in the above example, hydrogen bromide dissolves in water to form H+ and Br− ions, so it may be assumed that bromine is more electronegative than hydrogen. However, in principle, since the same electronegativities should be obtained for any two bonding compounds, the data are overdetermined, and the signs are unique once a reference point has been fixed (usually, for H or F).', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'As only differences in electronegativity are defined, it is necessary to choose an arbitrary reference point to construct a scale. Hydrogen was chosen as the reference, as it forms covalent bonds with a large variety of elements: its electronegativity was fixed first at 0, then in his famous book at 2.1 to avoid negative electronegativity figures, later revised to 2.20 by Allred. It is also necessary to decide which of the two elements is the more electronegative (equivalent to choosing one of the two possible signs for the square root). This is usually done using "chemical intuition": in the above example, hydrogen bromide dissolves in water to form H+ and Br− ions, so it may be assumed that bromine is more electronegative than hydrogen. However, in principle, since the same electronegativities should be obtained for any two bonding compounds, the data are overdetermined, and the signs are unique once a reference point has been fixed (usually, for H or F).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity: Pauling electronegativity', 'To calculate Pauling electronegativity for an element, it is necessary to have data on the dissociation energies of at least two types of covalent bonds formed by that element. A. L. Allred updated Pauling''s original values in 1961 to take account of the greater availability of thermodynamic data, and it is these "revised Pauling" values of the electronegativity that are most often used. The essential point of Pauling electronegativity is that there is an underlying, quite accurate, semi-empirical formula for dissociation energies, namely: These are approximate equations but they hold with good accuracy. Pauling obtained the first equation by noting that a bond can be approximately represented as a quantum mechanical superposition of a covalent bond and two ionic bond states. The covalent energy of a bond is approximately, by quantum mechanical calculations, the geometric mean of the two energies of covalent bonds of the same molecules, and there is additional energy that comes from ionic factors, i.e. polar character of the bond.', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'To calculate Pauling electronegativity for an element, it is necessary to have data on the dissociation energies of at least two types of covalent bonds formed by that element. A. L. Allred updated Pauling''s original values in 1961 to take account of the greater availability of thermodynamic data, and it is these "revised Pauling" values of the electronegativity that are most often used. The essential point of Pauling electronegativity is that there is an underlying, quite accurate, semi-empirical formula for dissociation energies, namely: These are approximate equations but they hold with good accuracy. Pauling obtained the first equation by noting that a bond can be approximately represented as a quantum mechanical superposition of a covalent bond and two ionic bond states. The covalent energy of a bond is approximately, by quantum mechanical calculations, the geometric mean of the two energies of covalent bonds of the same molecules, and there is additional energy that comes from ionic factors, i.e. polar character of the bond.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity: Pauling electronegativity', 'The geometric mean is approximately equal to the arithmetic mean—which is applied in the first formula above—when the energies are of a similar value, e.g., except for the highly electropositive elements, where there is a larger difference of two dissociation energies; the geometric mean is more accurate and almost always gives positive excess energy, due to ionic bonding. The square root of this excess energy, Pauling notes, is approximately additive, and hence one can introduce the electronegativity. Thus, it is these semi-empirical formulas for bond energy that underlie the concept of Pauling electronegativity. The formulas are approximate, but this rough approximation is good and gives the right intuition, with the notion of the polarity of the bond and some theoretical grounding in quantum mechanics. The electronegativities are then determined to best fit the data.', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The geometric mean is approximately equal to the arithmetic mean—which is applied in the first formula above—when the energies are of a similar value, e.g., except for the highly electropositive elements, where there is a larger difference of two dissociation energies; the geometric mean is more accurate and almost always gives positive excess energy, due to ionic bonding. The square root of this excess energy, Pauling notes, is approximately additive, and hence one can introduce the electronegativity. Thus, it is these semi-empirical formulas for bond energy that underlie the concept of Pauling electronegativity. The formulas are approximate, but this rough approximation is good and gives the right intuition, with the notion of the polarity of the bond and some theoretical grounding in quantum mechanics. The electronegativities are then determined to best fit the data.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Electronegativity: Pauling electronegativity', 'In more complex compounds, there is an additional error since electronegativity depends on the molecular environment of an atom. Also, the energy estimate can be only used for single, not for multiple bonds. The enthalpy of formation of a molecule containing only single bonds can subsequently be estimated based on an electronegativity table, and it depends on the constituents and the sum of squares of differences of electronegativities of all pairs of bonded atoms. Such a formula for estimating energy typically has a relative error on the order of 10% but can be used to get a rough qualitative idea and understanding of a molecule.', 'Wikipedia: Electronegativity', 'https://en.wikipedia.org/w/index.php?title=Electronegativity&oldid=1378985331', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In more complex compounds, there is an additional error since electronegativity depends on the molecular environment of an atom. Also, the energy estimate can be only used for single, not for multiple bonds. The enthalpy of formation of a molecule containing only single bonds can subsequently be estimated based on an electronegativity table, and it depends on the constituents and the sum of squares of differences of electronegativities of all pairs of bonded atoms. Such a formula for estimating energy typically has a relative error on the order of 10% but can be used to get a rough qualitative idea and understanding of a molecule.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond', 'A chemical bond is the association of atoms or ions to form molecules, crystals, and other structures. The bond may result from the electrostatic force between oppositely charged ions, as in ionic bonds; the sharing of electrons, as in covalent bonds; or some combination of these effects. Chemical bonds are described as having different strengths: there are "strong bonds" or "primary bonds" such as covalent, ionic, and metallic bonds, and "weak bonds" or "secondary bonds" such as dipole–dipole interactions, the London dispersion force, and hydrogen bonds. Since opposite electric charges attract, the negatively charged electrons surrounding the nucleus and the positively charged protons within a nucleus attract each other. Electrons shared between two nuclei will be attracted to both of them. "Constructive quantum mechanical wavefunction interference" stabilizes the paired nuclei (see Theories of chemical bonding). Bonded nuclei maintain an optimal distance (the bond distance) that balances attractive and repulsive effects, as explained quantitatively by quantum theory. The atoms in molecules, crystals, metals, and other forms of matter are held together by chemical bonds, which determine the structure and properties of matter.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'A chemical bond is the association of atoms or ions to form molecules, crystals, and other structures. The bond may result from the electrostatic force between oppositely charged ions, as in ionic bonds; the sharing of electrons, as in covalent bonds; or some combination of these effects. Chemical bonds are described as having different strengths: there are "strong bonds" or "primary bonds" such as covalent, ionic, and metallic bonds, and "weak bonds" or "secondary bonds" such as dipole–dipole interactions, the London dispersion force, and hydrogen bonds. Since opposite electric charges attract, the negatively charged electrons surrounding the nucleus and the positively charged protons within a nucleus attract each other. Electrons shared between two nuclei will be attracted to both of them. "Constructive quantum mechanical wavefunction interference" stabilizes the paired nuclei (see Theories of chemical bonding). Bonded nuclei maintain an optimal distance (the bond distance) that balances attractive and repulsive effects, as explained quantitatively by quantum theory. The atoms in molecules, crystals, metals, and other forms of matter are held together by chemical bonds, which determine the structure and properties of matter.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond', 'All bonds can be described by quantum theory, but, in practice, simplified rules and other theories allow chemists to predict the strength, directionality, and polarity of bonds. The octet rule and VSEPR theory are examples. More sophisticated theories are valence bond theory, which includes orbital hybridization and resonance, and molecular orbital theory, which includes the linear combination of atomic orbitals and ligand field theory. Electrostatics is used to describe bond polarities and the effects they have on chemical substances.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'All bonds can be described by quantum theory, but, in practice, simplified rules and other theories allow chemists to predict the strength, directionality, and polarity of bonds. The octet rule and VSEPR theory are examples. More sophisticated theories are valence bond theory, which includes orbital hybridization and resonance, and molecular orbital theory, which includes the linear combination of atomic orbitals and ligand field theory. Electrostatics is used to describe bond polarities and the effects they have on chemical substances.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Overview of main types of chemical bonds', 'A chemical bond is an attraction between atoms. This attraction may be seen as the result of different behaviors of the outermost or valence electrons of atoms. These behaviors merge into each other seamlessly in various circumstances, so that there is no clear line to be drawn between them. However it remains useful and customary to differentiate between different types of bond, which result in different properties of condensed matter. In the simplest view of a covalent bond, one or more electrons (often a pair of electrons) are drawn into the space between the two atomic nuclei. Energy is released by bond formation. This is not as a result of reduction in potential energy, because the attraction of the two electrons to the two protons is offset by the electron-electron and proton-proton repulsions. Instead, the release of energy (and hence stability of the bond) arises from the reduction in kinetic energy due to the electrons being in a more spatially distributed (i.e. longer de Broglie wavelength) orbital compared with each electron being confined closer to its respective nucleus. These bonds exist between two particular identifiable atoms and have a direction in space, allowing them to be shown as single connecting lines between atoms in drawings, or modeled as sticks between spheres in models.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'A chemical bond is an attraction between atoms. This attraction may be seen as the result of different behaviors of the outermost or valence electrons of atoms. These behaviors merge into each other seamlessly in various circumstances, so that there is no clear line to be drawn between them. However it remains useful and customary to differentiate between different types of bond, which result in different properties of condensed matter. In the simplest view of a covalent bond, one or more electrons (often a pair of electrons) are drawn into the space between the two atomic nuclei. Energy is released by bond formation. This is not as a result of reduction in potential energy, because the attraction of the two electrons to the two protons is offset by the electron-electron and proton-proton repulsions. Instead, the release of energy (and hence stability of the bond) arises from the reduction in kinetic energy due to the electrons being in a more spatially distributed (i.e. longer de Broglie wavelength) orbital compared with each electron being confined closer to its respective nucleus. These bonds exist between two particular identifiable atoms and have a direction in space, allowing them to be shown as single connecting lines between atoms in drawings, or modeled as sticks between spheres in models.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Overview of main types of chemical bonds', 'In a polar covalent bond, one or more electrons are unequally shared between two nuclei. Covalent bonds often result in the formation of small collections of better-connected atoms called molecules, which in solids and liquids are bound to other molecules by forces that are often much weaker than the covalent bonds that hold the molecules internally together. Such weak intermolecular bonds give organic molecular substances, such as waxes and oils, their soft bulk character, and their low melting points (in liquids, molecules must cease most structured or oriented contact with each other). When covalent bonds link long chains of atoms in large molecules, however (as in polymers such as nylon), or when covalent bonds extend in networks through solids that are not composed of discrete molecules (such as diamond, quartz, or the silicate minerals in many types of rock) then the structures that result may be both strong and tough, at least in the direction oriented correctly with networks of covalent bonds. Also, the melting points of such covalent polymers and networks increase greatly.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In a polar covalent bond, one or more electrons are unequally shared between two nuclei. Covalent bonds often result in the formation of small collections of better-connected atoms called molecules, which in solids and liquids are bound to other molecules by forces that are often much weaker than the covalent bonds that hold the molecules internally together. Such weak intermolecular bonds give organic molecular substances, such as waxes and oils, their soft bulk character, and their low melting points (in liquids, molecules must cease most structured or oriented contact with each other). When covalent bonds link long chains of atoms in large molecules, however (as in polymers such as nylon), or when covalent bonds extend in networks through solids that are not composed of discrete molecules (such as diamond, quartz, or the silicate minerals in many types of rock) then the structures that result may be both strong and tough, at least in the direction oriented correctly with networks of covalent bonds. Also, the melting points of such covalent polymers and networks increase greatly.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Overview of main types of chemical bonds', 'In a simplified view of an ionic bond, the bonding electron is not shared at all, but transferred. In this type of bond, the outer atomic orbital of one atom has a vacancy which allows the addition of one or more electrons. These newly added electrons potentially occupy a lower energy-state (effectively closer to more nuclear charge) than they experience in a different atom. Thus, one nucleus offers a more tightly bound position to an electron than does another nucleus, with the result that one atom may transfer an electron to the other. This transfer causes one atom to assume a net positive charge, and the other to assume a net negative charge. The bond then results from electrostatic attraction between the positive and negatively charged ions. Ionic bonds may be seen as extreme examples of polarization in covalent bonds. Often, such bonds have no particular orientation in space, since they result from equal electrostatic attraction of each ion to all ions around them. Ionic bonds are strong (and thus ionic substances require high temperatures to melt) but also brittle, since the forces between ions are short-range and do not easily bridge cracks and fractures. This type of bond gives rise to the physical characteristics of crystals of classic mineral salts, such as table salt.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In a simplified view of an ionic bond, the bonding electron is not shared at all, but transferred. In this type of bond, the outer atomic orbital of one atom has a vacancy which allows the addition of one or more electrons. These newly added electrons potentially occupy a lower energy-state (effectively closer to more nuclear charge) than they experience in a different atom. Thus, one nucleus offers a more tightly bound position to an electron than does another nucleus, with the result that one atom may transfer an electron to the other. This transfer causes one atom to assume a net positive charge, and the other to assume a net negative charge. The bond then results from electrostatic attraction between the positive and negatively charged ions. Ionic bonds may be seen as extreme examples of polarization in covalent bonds. Often, such bonds have no particular orientation in space, since they result from equal electrostatic attraction of each ion to all ions around them. Ionic bonds are strong (and thus ionic substances require high temperatures to melt) but also brittle, since the forces between ions are short-range and do not easily bridge cracks and fractures. This type of bond gives rise to the physical characteristics of crystals of classic mineral salts, such as table salt.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Overview of main types of chemical bonds', 'A less often mentioned type of bonding is metallic bonding. In this type of bonding, each atom in a metal donates one or more electrons to a "sea" of electrons that reside between many metal atoms. In this sea, each electron is free (by virtue of its wave nature) to be associated with a great many atoms at once. The bond results because the metal atoms become somewhat positively charged due to loss of their electrons while the electrons remain attracted to many atoms, without being part of any given atom. Metallic bonding may be seen as an extreme example of delocalization of electrons over a large system of covalent bonds, in which every atom participates. This type of bonding is often very strong (resulting in the tensile strength of metals). However, metallic bonding is more collective in nature than other types, and so they allow metal crystals to more easily deform, because they are composed of atoms attracted to each other, but not in any particularly-oriented ways. This results in the malleability of metals. The cloud of electrons in metallic bonding causes the characteristically good electrical and thermal conductivity of metals, and also their shiny lustre that reflects most frequencies of white light.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'A less often mentioned type of bonding is metallic bonding. In this type of bonding, each atom in a metal donates one or more electrons to a "sea" of electrons that reside between many metal atoms. In this sea, each electron is free (by virtue of its wave nature) to be associated with a great many atoms at once. The bond results because the metal atoms become somewhat positively charged due to loss of their electrons while the electrons remain attracted to many atoms, without being part of any given atom. Metallic bonding may be seen as an extreme example of delocalization of electrons over a large system of covalent bonds, in which every atom participates. This type of bonding is often very strong (resulting in the tensile strength of metals). However, metallic bonding is more collective in nature than other types, and so they allow metal crystals to more easily deform, because they are composed of atoms attracted to each other, but not in any particularly-oriented ways. This results in the malleability of metals. The cloud of electrons in metallic bonding causes the characteristically good electrical and thermal conductivity of metals, and also their shiny lustre that reflects most frequencies of white light.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Bonds in chemical formulas', 'Because atoms and molecules are three-dimensional, it is difficult to use a single method to indicate orbitals and bonds. In molecular formulas the chemical bonds (binding orbitals) between atoms are indicated in different ways depending on the type of discussion. Sometimes, some details are neglected. For example, in organic chemistry one is sometimes concerned only with the functional group of the molecule. Thus, the molecular formula of ethanol may be written in conformational form, three-dimensional form, full two-dimensional form (indicating every bond with no three-dimensional directions), compressed two-dimensional form (CH3–CH2–OH), by separating the functional group from another part of the molecule (C2H5OH), or by its atomic constituents (C2H6O), according to what is discussed. Sometimes, even the non-bonding valence shell electrons (with the two-dimensional approximate directions) are marked, e.g. for elemental carbon.''C''. Some chemists may also mark the respective orbitals, e.g. the hypothetical ethene−4 anion (\/C=C/\ −4) indicating the possibility of bond formation.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Because atoms and molecules are three-dimensional, it is difficult to use a single method to indicate orbitals and bonds. In molecular formulas the chemical bonds (binding orbitals) between atoms are indicated in different ways depending on the type of discussion. Sometimes, some details are neglected. For example, in organic chemistry one is sometimes concerned only with the functional group of the molecule. Thus, the molecular formula of ethanol may be written in conformational form, three-dimensional form, full two-dimensional form (indicating every bond with no three-dimensional directions), compressed two-dimensional form (CH3–CH2–OH), by separating the functional group from another part of the molecule (C2H5OH), or by its atomic constituents (C2H6O), according to what is discussed. Sometimes, even the non-bonding valence shell electrons (with the two-dimensional approximate directions) are marked, e.g. for elemental carbon.''C''. Some chemists may also mark the respective orbitals, e.g. the hypothetical ethene−4 anion (\/C=C/\ −4) indicating the possibility of bond formation.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Chemical bond: Strong chemical bonds', 'Strong chemical bonds are the intramolecular forces that hold atoms together in molecules. A strong chemical bond is formed from the transfer or sharing of electrons between atomic centers and relies on the electrostatic attraction between the protons in nuclei and the electrons in the orbitals. The types of strong bond differ due to the difference in electronegativity of the constituent elements. Electronegativity is the tendency for an atom of a given chemical element to attract shared electrons when forming a chemical bond, where the higher the associated electronegativity then the more it attracts electrons. Electronegativity serves as a simple way to quantitatively estimate the bond energy, which characterizes a bond along the continuous scale from covalent to ionic bonding. A large difference in electronegativity leads to more polar (ionic) character in the bond.', 'Wikipedia: Chemical bond', 'https://en.wikipedia.org/w/index.php?title=Chemical_bond&oldid=1368837112', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Strong chemical bonds are the intramolecular forces that hold atoms together in molecules. A strong chemical bond is formed from the transfer or sharing of electrons between atomic centers and relies on the electrostatic attraction between the protons in nuclei and the electrons in the orbitals. The types of strong bond differ due to the difference in electronegativity of the constituent elements. Electronegativity is the tendency for an atom of a given chemical element to attract shared electrons when forming a chemical bond, where the higher the associated electronegativity then the more it attracts electrons. Electronegativity serves as a simple way to quantitatively estimate the bond energy, which characterizes a bond along the continuous scale from covalent to ionic bonding. A large difference in electronegativity leads to more polar (ionic) character in the bond.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory', 'Valence shell electron pair repulsion (VSEPR) theory ( VESP-ər, və-SEP-ər) is a model used in chemistry to predict the geometry of individual molecules from the number of electron pairs surrounding their central atoms. It is also named the Gillespie-Nyholm theory after its two main developers, Ronald Gillespie and Ronald Nyholm but it is also called the Sidgwick-Powell theory after earlier work by Nevil Sidgwick and Herbert Marcus Powell. The premise of VSEPR is that the valence electron pairs surrounding an atom tend to repel each other. The greater the repulsion, the higher in energy (less stable) the molecule is. Therefore, the VSEPR-predicted molecular geometry of a molecule is the one that has as little of this repulsion as possible. Gillespie has emphasized that the electron-electron repulsion due to the Pauli exclusion principle is more important in determining molecular geometry than the electrostatic repulsion. The insights of VSEPR theory are derived from topological analysis of the electron density of molecules. Such quantum chemical topology (QCT) methods include the electron localization function (ELF) and the quantum theory of atoms in molecules (AIM or QTAIM).', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Valence shell electron pair repulsion (VSEPR) theory ( VESP-ər, və-SEP-ər) is a model used in chemistry to predict the geometry of individual molecules from the number of electron pairs surrounding their central atoms. It is also named the Gillespie-Nyholm theory after its two main developers, Ronald Gillespie and Ronald Nyholm but it is also called the Sidgwick-Powell theory after earlier work by Nevil Sidgwick and Herbert Marcus Powell. The premise of VSEPR is that the valence electron pairs surrounding an atom tend to repel each other. The greater the repulsion, the higher in energy (less stable) the molecule is. Therefore, the VSEPR-predicted molecular geometry of a molecule is the one that has as little of this repulsion as possible. Gillespie has emphasized that the electron-electron repulsion due to the Pauli exclusion principle is more important in determining molecular geometry than the electrostatic repulsion. The insights of VSEPR theory are derived from topological analysis of the electron density of molecules. Such quantum chemical topology (QCT) methods include the electron localization function (ELF) and the quantum theory of atoms in molecules (AIM or QTAIM).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Overview', 'VSEPR theory is used to predict the arrangement of electron pairs around central atoms in molecules, especially simple and symmetric molecules. A central atom is defined in this theory as an atom which is bonded to two or more other atoms, while a terminal atom is bonded to only one other atom. For example, in the molecule methyl isocyanate (H3C-N=C=O), the two carbons and one nitrogen are central atoms, and the three hydrogens and one oxygen are terminal atoms. The geometry of the central atoms and their non-bonding electron pairs in turn determine the geometry of the larger whole molecule. The number of electron pairs in the valence shell of a central atom is determined after drawing the Lewis structure of the molecule, and expanding it to show all bonding groups and lone pairs of electrons. In VSEPR theory, a double bond or triple bond is treated as a single bonding group. The sum of the number of atoms bonded to a central atom and the number of lone pairs formed by its nonbonding valence electrons is known as the central atom''s steric number.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'VSEPR theory is used to predict the arrangement of electron pairs around central atoms in molecules, especially simple and symmetric molecules. A central atom is defined in this theory as an atom which is bonded to two or more other atoms, while a terminal atom is bonded to only one other atom. For example, in the molecule methyl isocyanate (H3C-N=C=O), the two carbons and one nitrogen are central atoms, and the three hydrogens and one oxygen are terminal atoms. The geometry of the central atoms and their non-bonding electron pairs in turn determine the geometry of the larger whole molecule. The number of electron pairs in the valence shell of a central atom is determined after drawing the Lewis structure of the molecule, and expanding it to show all bonding groups and lone pairs of electrons. In VSEPR theory, a double bond or triple bond is treated as a single bonding group. The sum of the number of atoms bonded to a central atom and the number of lone pairs formed by its nonbonding valence electrons is known as the central atom''s steric number.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Overview', 'The electron pairs (or groups if multiple bonds are present) are assumed to lie on the surface of a sphere centered on the central atom and tend to occupy positions that minimize their mutual repulsions by maximizing the distance between them. The number of electron pairs (or groups), therefore, determines the overall geometry that they will adopt. For example, when there are two electron pairs surrounding the central atom, their mutual repulsion is minimal when they lie at opposite poles of the sphere. Therefore, the central atom is predicted to adopt a linear geometry. If there are 3 electron pairs surrounding the central atom, their repulsion is minimized by placing them at the vertices of an equilateral triangle centered on the atom. Therefore, the predicted geometry is trigonal. Likewise, for 4 electron pairs, the optimal arrangement is tetrahedral.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The electron pairs (or groups if multiple bonds are present) are assumed to lie on the surface of a sphere centered on the central atom and tend to occupy positions that minimize their mutual repulsions by maximizing the distance between them. The number of electron pairs (or groups), therefore, determines the overall geometry that they will adopt. For example, when there are two electron pairs surrounding the central atom, their mutual repulsion is minimal when they lie at opposite poles of the sphere. Therefore, the central atom is predicted to adopt a linear geometry. If there are 3 electron pairs surrounding the central atom, their repulsion is minimized by placing them at the vertices of an equilateral triangle centered on the atom. Therefore, the predicted geometry is trigonal. Likewise, for 4 electron pairs, the optimal arrangement is tetrahedral.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Overview', 'As a tool in predicting the geometry adopted with a given number of electron pairs, an often used physical demonstration of the principle of minimal electron pair repulsion utilizes inflated balloons. Through handling, balloons acquire a slight surface electrostatic charge that results in the adoption of roughly the same geometries when they are tied together at their stems as the corresponding number of electron pairs. For example, five balloons tied together adopt the trigonal bipyramidal geometry, just as do the five bonding pairs of a PCl5 molecule.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'As a tool in predicting the geometry adopted with a given number of electron pairs, an often used physical demonstration of the principle of minimal electron pair repulsion utilizes inflated balloons. Through handling, balloons acquire a slight surface electrostatic charge that results in the adoption of roughly the same geometries when they are tied together at their stems as the corresponding number of electron pairs. For example, five balloons tied together adopt the trigonal bipyramidal geometry, just as do the five bonding pairs of a PCl5 molecule.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Steric number', 'The steric number of a central atom in a molecule is the number of atoms bonded to that central atom, called its coordination number, plus the number of lone pairs of valence electrons on the central atom. In the molecule SF4, for example, the central sulfur atom has four ligands; the coordination number of sulfur is four. In addition to the four ligands, sulfur also has one lone pair in this molecule. Thus, the steric number is 4 + 1 = 5. Alternatively, the steric number can be determined for main-group elements using an algebraic electron-counting formula. This method sums the relevant valence electrons and divides by 2 to determine the number of electron pairs (domains). The formula is: M is the number of atoms bonded to the central atom by single bonds. There are 4 bonded fluorine atoms, each contributing 1 electron (M = 4). A steric number of 6 corresponds to an octahedral electron geometry. Since there are 4 bonded atoms, the molecule contains 2 lone pairs (6 − 4 = 2), resulting in a square planar molecular geometry.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The steric number of a central atom in a molecule is the number of atoms bonded to that central atom, called its coordination number, plus the number of lone pairs of valence electrons on the central atom. In the molecule SF4, for example, the central sulfur atom has four ligands; the coordination number of sulfur is four. In addition to the four ligands, sulfur also has one lone pair in this molecule. Thus, the steric number is 4 + 1 = 5. Alternatively, the steric number can be determined for main-group elements using an algebraic electron-counting formula. This method sums the relevant valence electrons and divides by 2 to determine the number of electron pairs (domains). The formula is: M is the number of atoms bonded to the central atom by single bonds. There are 4 bonded fluorine atoms, each contributing 1 electron (M = 4). A steric number of 6 corresponds to an octahedral electron geometry. Since there are 4 bonded atoms, the molecule contains 2 lone pairs (6 − 4 = 2), resulting in a square planar molecular geometry.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Degree of repulsion', 'The overall geometry is further refined by distinguishing between bonding and nonbonding electron pairs. The bonding electron pair shared in a sigma bond with an adjacent atom lies further from the central atom than a nonbonding (lone) pair of that atom, which is held close to its positively charged nucleus. VSEPR theory therefore views repulsion by the lone pair to be greater than the repulsion by a bonding pair. As such, when a molecule has 2 interactions with different degrees of repulsion, VSEPR theory predicts the structure where lone pairs occupy positions that allow them to experience less repulsion. Lone pair–lone pair (lp–lp) repulsions are considered stronger than lone pair–bonding pair (lp–bp) repulsions, which in turn are considered stronger than bonding pair–bonding pair (bp–bp) repulsions, distinctions that then guide decisions about overall geometry when 2 or more non-equivalent positions are possible. For instance, when 5 valence electron pairs surround a central atom, they adopt a trigonal bipyramidal molecular geometry with two collinear axial positions and three equatorial positions. An electron pair in an axial position has three close equatorial neighbors only 90° away and a fourth much farther at 180°, while an equatorial electron pair has only two adjacent pairs at 90° and two at 120°. The repulsion from the close neighbors at 90° is more important, so that the axial positions experience more repulsion than the equatorial positions; hence, when there are lone pairs, they tend to occupy equatorial positions as shown in the diagrams of the next section for steric number five.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The overall geometry is further refined by distinguishing between bonding and nonbonding electron pairs. The bonding electron pair shared in a sigma bond with an adjacent atom lies further from the central atom than a nonbonding (lone) pair of that atom, which is held close to its positively charged nucleus. VSEPR theory therefore views repulsion by the lone pair to be greater than the repulsion by a bonding pair. As such, when a molecule has 2 interactions with different degrees of repulsion, VSEPR theory predicts the structure where lone pairs occupy positions that allow them to experience less repulsion. Lone pair–lone pair (lp–lp) repulsions are considered stronger than lone pair–bonding pair (lp–bp) repulsions, which in turn are considered stronger than bonding pair–bonding pair (bp–bp) repulsions, distinctions that then guide decisions about overall geometry when 2 or more non-equivalent positions are possible. For instance, when 5 valence electron pairs surround a central atom, they adopt a trigonal bipyramidal molecular geometry with two collinear axial positions and three equatorial positions. An electron pair in an axial position has three close equatorial neighbors only 90° away and a fourth much farther at 180°, while an equatorial electron pair has only two adjacent pairs at 90° and two at 120°. The repulsion from the close neighbors at 90° is more important, so that the axial positions experience more repulsion than the equatorial positions; hence, when there are lone pairs, they tend to occupy equatorial positions as shown in the diagrams of the next section for steric number five.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: Degree of repulsion', 'The difference between lone pairs and bonding pairs may also be used to rationalize deviations from idealized geometries. For example, the H2O molecule has four electron pairs in its valence shell: two lone pairs and two bond pairs. The four electron pairs are spread so as to point roughly towards the apices of a tetrahedron. However, the bond angle between the two O–H bonds is only 104.5°, rather than the 109.5° of a regular tetrahedron, because the two lone pairs (whose density or probability envelopes lie closer to the oxygen nucleus) exert a greater mutual repulsion than the two bond pairs. A bond of higher bond order also exerts greater repulsion since the pi bond electrons contribute. For example, in isobutylene, (H3C)2C=CH2, the H3C−C=C angle (124°) is larger than the H3C−C−CH3 angle (111.5°). However, in the carbonate ion, CO2−3, all three C−O bonds are equivalent with angles of 120° due to resonance.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The difference between lone pairs and bonding pairs may also be used to rationalize deviations from idealized geometries. For example, the H2O molecule has four electron pairs in its valence shell: two lone pairs and two bond pairs. The four electron pairs are spread so as to point roughly towards the apices of a tetrahedron. However, the bond angle between the two O–H bonds is only 104.5°, rather than the 109.5° of a regular tetrahedron, because the two lone pairs (whose density or probability envelopes lie closer to the oxygen nucleus) exert a greater mutual repulsion than the two bond pairs. A bond of higher bond order also exerts greater repulsion since the pi bond electrons contribute. For example, in isobutylene, (H3C)2C=CH2, the H3C−C=C angle (124°) is larger than the H3C−C−CH3 angle (111.5°). However, in the carbonate ion, CO2−3, all three C−O bonds are equivalent with angles of 120° due to resonance.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'VSEPR theory: AXE method', 'The "AXE method" of electron counting is commonly used when applying the VSEPR theory. The electron pairs around a central atom are represented by a formula AXmEn, where A represents the central atom and always has an implied subscript one. Each X represents a ligand (an atom bonded to A). Each E represents a lone pair of electrons on the central atom. The total number of X and E is known as the steric number. For example, in a molecule AX3E2, the atom A has a steric number of 5. When the substituent (X) atoms are not all the same, the geometry is still approximately valid, but the bond angles may be slightly different from the ones where all the outside atoms are the same. For example, the double-bond carbons in alkenes like C2H4 are AX3E0, but the bond angles are not all exactly 120°. Likewise, SOCl2 is AX3E1, but because the X substituents are not identical, the X–A–X angles are not all equal. Based on the steric number and distribution of Xs and Es, VSEPR theory makes the predictions in the following tables.', 'Wikipedia: VSEPR theory', 'https://en.wikipedia.org/w/index.php?title=VSEPR_theory&oldid=1378664958', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The "AXE method" of electron counting is commonly used when applying the VSEPR theory. The electron pairs around a central atom are represented by a formula AXmEn, where A represents the central atom and always has an implied subscript one. Each X represents a ligand (an atom bonded to A). Each E represents a lone pair of electrons on the central atom. The total number of X and E is known as the steric number. For example, in a molecule AX3E2, the atom A has a steric number of 5. When the substituent (X) atoms are not all the same, the geometry is still approximately valid, but the bond angles may be slightly different from the ones where all the outside atoms are the same. For example, the double-bond carbons in alkenes like C2H4 are AX3E0, but the bond angles are not all exactly 120°. Likewise, SOCl2 is AX3E1, but because the X substituents are not identical, the X–A–X angles are not all equal. Based on the steric number and distribution of Xs and Es, VSEPR theory makes the predictions in the following tables.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation', 'In chemistry, orbital hybridisation (or hybridization) is the concept of mixing atomic orbitals to form new hybrid orbitals (with different energies, shapes, etc., than the component atomic orbitals) suitable for the pairing of electrons to form chemical bonds in valence bond theory. For example, in a carbon atom which forms four single bonds, the valence-shell s orbital combines with three valence-shell p orbitals to form four equivalent sp3 mixtures in a tetrahedral arrangement around the carbon to bond to four different atoms. Hybrid orbitals are useful in the explanation of molecular geometry and atomic bonding properties and are symmetrically disposed in space. Usually hybrid orbitals are formed by mixing atomic orbitals of comparable energies.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In chemistry, orbital hybridisation (or hybridization) is the concept of mixing atomic orbitals to form new hybrid orbitals (with different energies, shapes, etc., than the component atomic orbitals) suitable for the pairing of electrons to form chemical bonds in valence bond theory. For example, in a carbon atom which forms four single bonds, the valence-shell s orbital combines with three valence-shell p orbitals to form four equivalent sp3 mixtures in a tetrahedral arrangement around the carbon to bond to four different atoms. Hybrid orbitals are useful in the explanation of molecular geometry and atomic bonding properties and are symmetrically disposed in space. Usually hybrid orbitals are formed by mixing atomic orbitals of comparable energies.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: History and uses', 'Chemist Linus Pauling first developed the hybridisation theory in 1931 to explain the structure of simple molecules such as methane (CH4) using atomic orbitals. Pauling pointed out that a carbon atom forms four bonds by using one s and three p orbitals, so that "it might be inferred" that a carbon atom would form three bonds at right angles (using p orbitals) and a fourth weaker bond using the s orbital in some arbitrary direction. In reality, methane has four C–H bonds of equivalent strength. The angle between any two bonds is the tetrahedral bond angle of 109°28'' (around 109.5°). Pauling supposed that in the presence of four hydrogen atoms, the s and p orbitals form four equivalent combinations which he called hybrid orbitals. Each hybrid is denoted sp3 to indicate its composition, and is directed along one of the four C–H bonds. This concept was developed for such simple chemical systems, but the approach was later applied more widely, and today it is considered an effective heuristic for rationalizing the structures of organic compounds. It gives a simple orbital picture equivalent to Lewis structures.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Chemist Linus Pauling first developed the hybridisation theory in 1931 to explain the structure of simple molecules such as methane (CH4) using atomic orbitals. Pauling pointed out that a carbon atom forms four bonds by using one s and three p orbitals, so that "it might be inferred" that a carbon atom would form three bonds at right angles (using p orbitals) and a fourth weaker bond using the s orbital in some arbitrary direction. In reality, methane has four C–H bonds of equivalent strength. The angle between any two bonds is the tetrahedral bond angle of 109°28'' (around 109.5°). Pauling supposed that in the presence of four hydrogen atoms, the s and p orbitals form four equivalent combinations which he called hybrid orbitals. Each hybrid is denoted sp3 to indicate its composition, and is directed along one of the four C–H bonds. This concept was developed for such simple chemical systems, but the approach was later applied more widely, and today it is considered an effective heuristic for rationalizing the structures of organic compounds. It gives a simple orbital picture equivalent to Lewis structures.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: History and uses', 'Hybridisation theory is an integral part of organic chemistry, one of the most compelling examples being Baldwin''s rules. For drawing reaction mechanisms sometimes a classical bonding picture is needed with two atoms sharing two electrons. Hybridisation theory explains bonding in alkenes and methane. The amount of p character or s character, which is decided mainly by orbital hybridisation, can be used to reliably predict molecular properties such as acidity or basicity.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Hybridisation theory is an integral part of organic chemistry, one of the most compelling examples being Baldwin''s rules. For drawing reaction mechanisms sometimes a classical bonding picture is needed with two atoms sharing two electrons. Hybridisation theory explains bonding in alkenes and methane. The amount of p character or s character, which is decided mainly by orbital hybridisation, can be used to reliably predict molecular properties such as acidity or basicity.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: Overview', 'Orbitals are a model representation of the behavior of electrons within molecules. In the case of simple hybridization, this approximation is based on atomic orbitals, similar to those obtained for the hydrogen atom, the only neutral atom for which the Schrödinger equation can be solved exactly. In heavier atoms, such as carbon, nitrogen, and oxygen, the atomic orbitals used are the 2s and 2p orbitals, similar to excited state orbitals for hydrogen. Hybrid orbitals are assumed to be mixtures of atomic orbitals, superimposed on each other in various proportions. For example, in methane, the C hybrid orbital which forms each carbon–hydrogen bond consists of 25% s character and 75% p character and is thus described as sp3 (read as s-p-three) hybridised. Quantum mechanics describes this hybrid as an sp3 wavefunction of the form , where N is a normalisation constant (here 1/2) and pσ is a p orbital directed along the C-H axis to form a sigma bond. The ratio of coefficients (denoted λ in general) is in this example. Since the electron density associated with an orbital is proportional to the square of the wavefunction, the ratio of p-character to s-character is λ2 = 3. The p character or the weight of the p component is N2λ2 = 3/4.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Orbitals are a model representation of the behavior of electrons within molecules. In the case of simple hybridization, this approximation is based on atomic orbitals, similar to those obtained for the hydrogen atom, the only neutral atom for which the Schrödinger equation can be solved exactly. In heavier atoms, such as carbon, nitrogen, and oxygen, the atomic orbitals used are the 2s and 2p orbitals, similar to excited state orbitals for hydrogen. Hybrid orbitals are assumed to be mixtures of atomic orbitals, superimposed on each other in various proportions. For example, in methane, the C hybrid orbital which forms each carbon–hydrogen bond consists of 25% s character and 75% p character and is thus described as sp3 (read as s-p-three) hybridised. Quantum mechanics describes this hybrid as an sp3 wavefunction of the form , where N is a normalisation constant (here 1/2) and pσ is a p orbital directed along the C-H axis to form a sigma bond. The ratio of coefficients (denoted λ in general) is in this example. Since the electron density associated with an orbital is proportional to the square of the wavefunction, the ratio of p-character to s-character is λ2 = 3. The p character or the weight of the p component is N2λ2 = 3/4.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: sp3', 'Hybridisation describes the bonding of atoms from an atom''s point of view. For a tetrahedrally coordinated carbon (e.g., methane CH4), the carbon should have 4 orbitals directed towards the 4 hydrogen atoms. Carbon''s ground state configuration is 1s2 2s2 2p2 or more easily read: This diagram suggests that the carbon atom could use its two singly occupied p-type orbitals to form two covalent bonds with two hydrogen atoms in a methylene (CH2) molecule, with a hypothetical bond angle of 90° corresponding to the angle between two p orbitals on the same atom. However the true H–C–H angle in singlet methylene is about 102° which implies the presence of some orbital hybridisation. The carbon atom can also bond to four hydrogen atoms in methane by an excitation (or promotion) of an electron from the doubly occupied 2s orbital to the empty 2p orbital, producing four singly occupied orbitals. The energy released by the formation of two additional bonds more than compensates for the excitation energy required, energetically favoring the formation of four C-H bonds.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Hybridisation describes the bonding of atoms from an atom''s point of view. For a tetrahedrally coordinated carbon (e.g., methane CH4), the carbon should have 4 orbitals directed towards the 4 hydrogen atoms. Carbon''s ground state configuration is 1s2 2s2 2p2 or more easily read: This diagram suggests that the carbon atom could use its two singly occupied p-type orbitals to form two covalent bonds with two hydrogen atoms in a methylene (CH2) molecule, with a hypothetical bond angle of 90° corresponding to the angle between two p orbitals on the same atom. However the true H–C–H angle in singlet methylene is about 102° which implies the presence of some orbital hybridisation. The carbon atom can also bond to four hydrogen atoms in methane by an excitation (or promotion) of an electron from the doubly occupied 2s orbital to the empty 2p orbital, producing four singly occupied orbitals. The energy released by the formation of two additional bonds more than compensates for the excitation energy required, energetically favoring the formation of four C-H bonds.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: sp3', 'According to quantum mechanics, the lowest energy is obtained if the four bonds are equivalent, which requires that they are formed from equivalent orbitals on the carbon. A set of four equivalent orbitals can be obtained that are linear combinations of the valence-shell (core orbitals are almost never involved in bonding) s and p wave functions, which are the four sp3 hybrids. In CH4, four sp3 hybrid orbitals are overlapped by the four hydrogens'' 1s orbitals, yielding four σ (sigma) bonds (that is, four single covalent bonds) of equal length and strength.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'According to quantum mechanics, the lowest energy is obtained if the four bonds are equivalent, which requires that they are formed from equivalent orbitals on the carbon. A set of four equivalent orbitals can be obtained that are linear combinations of the valence-shell (core orbitals are almost never involved in bonding) s and p wave functions, which are the four sp3 hybrids. In CH4, four sp3 hybrid orbitals are overlapped by the four hydrogens'' 1s orbitals, yielding four σ (sigma) bonds (that is, four single covalent bonds) of equal length and strength.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: sp2', 'Other carbon compounds and other molecules may be explained in a similar way. For example, ethylene (C2H4) has a double bond between the carbons. For this molecule, carbon sp2 hybridises, because one π (pi) bond is required for the double bond between the carbons and only three σ bonds are formed per carbon atom. In sp2 hybridisation the 2s orbital is mixed with only two of the three available 2p orbitals, usually denoted 2px and 2py. The third 2p orbital (2pz) remains unhybridised. forming a total of three sp2 orbitals with one remaining p orbital. In ethylene, the two carbon atoms form a σ bond by overlapping one sp2 orbital from each carbon atom. The π bond between the carbon atoms perpendicular to the molecular plane is formed by 2p–2p overlap. Each carbon atom forms covalent C–H bonds with two hydrogens by s–sp2 overlap, all with 120° bond angles. The hydrogen–carbon bonds are all of equal strength and length, in agreement with experimental data.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Other carbon compounds and other molecules may be explained in a similar way. For example, ethylene (C2H4) has a double bond between the carbons. For this molecule, carbon sp2 hybridises, because one π (pi) bond is required for the double bond between the carbons and only three σ bonds are formed per carbon atom. In sp2 hybridisation the 2s orbital is mixed with only two of the three available 2p orbitals, usually denoted 2px and 2py. The third 2p orbital (2pz) remains unhybridised. forming a total of three sp2 orbitals with one remaining p orbital. In ethylene, the two carbon atoms form a σ bond by overlapping one sp2 orbital from each carbon atom. The π bond between the carbon atoms perpendicular to the molecular plane is formed by 2p–2p overlap. Each carbon atom forms covalent C–H bonds with two hydrogens by s–sp2 overlap, all with 120° bond angles. The hydrogen–carbon bonds are all of equal strength and length, in agreement with experimental data.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Orbital hybridisation: sp', 'The chemical bonding in compounds such as alkynes with triple bonds is explained by sp hybridization. In this model, the 2s orbital is mixed with only one of the three p orbitals, resulting in two sp orbitals and two remaining p orbitals. The chemical bonding in acetylene (ethyne) (C2H2) consists of sp–sp overlap between the two carbon atoms forming a σ bond and two additional π bonds formed by p–p overlap. Each carbon also bonds to hydrogen in a σ s–sp overlap at 180° angles.', 'Wikipedia: Orbital hybridisation', 'https://en.wikipedia.org/w/index.php?title=Orbital_hybridisation&oldid=1379117093', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The chemical bonding in compounds such as alkynes with triple bonds is explained by sp hybridization. In this model, the 2s orbital is mixed with only one of the three p orbitals, resulting in two sp orbitals and two remaining p orbitals. The chemical bonding in acetylene (ethyne) (C2H2) consists of sp–sp overlap between the two carbon atoms forming a σ bond and two additional π bonds formed by p–p overlap. Each carbon also bonds to hydrogen in a σ s–sp overlap at 180° angles.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force', 'An intermolecular force (IMF; also secondary force) is the force that mediates interaction between molecules, including the electromagnetic forces of attraction or repulsion which act between atoms and other types of neighbouring particles (e.g. atoms or ions). Intermolecular forces are weak relative to intramolecular forces – the forces which hold a molecule together. For example, the covalent bond, involving sharing electron pairs between atoms, is much stronger than the forces present between neighboring molecules. Both sets of forces are essential parts of force fields frequently used in molecular mechanics. The first reference to the nature of microscopic forces is found in Alexis Clairaut''s work Théorie de la figure de la Terre, published in Paris in 1743. Other scientists who have contributed to the investigation of microscopic forces include: Laplace, Gauss, Maxwell, Boltzmann and Pauling. Van der Waals forces – Keesom force, Debye force, and London dispersion force Information on intermolecular forces is obtained by macroscopic measurements of properties like viscosity, pressure, volume, temperature (PVT) data. The link to microscopic aspects is given by virial coefficients and intermolecular pair potentials, such as the Mie potential, Buckingham potential or Lennard-Jones potential.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'An intermolecular force (IMF; also secondary force) is the force that mediates interaction between molecules, including the electromagnetic forces of attraction or repulsion which act between atoms and other types of neighbouring particles (e.g. atoms or ions). Intermolecular forces are weak relative to intramolecular forces – the forces which hold a molecule together. For example, the covalent bond, involving sharing electron pairs between atoms, is much stronger than the forces present between neighboring molecules. Both sets of forces are essential parts of force fields frequently used in molecular mechanics. The first reference to the nature of microscopic forces is found in Alexis Clairaut''s work Théorie de la figure de la Terre, published in Paris in 1743. Other scientists who have contributed to the investigation of microscopic forces include: Laplace, Gauss, Maxwell, Boltzmann and Pauling. Van der Waals forces – Keesom force, Debye force, and London dispersion force Information on intermolecular forces is obtained by macroscopic measurements of properties like viscosity, pressure, volume, temperature (PVT) data. The link to microscopic aspects is given by virial coefficients and intermolecular pair potentials, such as the Mie potential, Buckingham potential or Lennard-Jones potential.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force', 'In the broadest sense, it can be understood as such interactions between any particles (molecules, atoms, ions and molecular ions) in which the formation of chemical (that is, ionic, covalent or metallic) bonds does not occur. In other words, these interactions are significantly weaker than covalent ones and do not lead to a significant restructuring of the electronic structure of the interacting particles. (This is only partially true. For example, all enzymatic and catalytic reactions begin with a weak intermolecular interaction between a substrate and an enzyme or a molecule with a catalyst, but several such weak interactions with the required spatial configuration of the active center of the enzyme lead to significant restructuring in the energy states of molecules or substrates, all of which ultimately leads to the breaking of some and the formation of other covalent chemical bonds. Strictly speaking, all enzymatic reactions begin with intermolecular interactions between the substrate and the enzyme, therefore the importance of these interactions is especially great in biochemistry and molecular biology, and is the basis of enzymology).', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'In the broadest sense, it can be understood as such interactions between any particles (molecules, atoms, ions and molecular ions) in which the formation of chemical (that is, ionic, covalent or metallic) bonds does not occur. In other words, these interactions are significantly weaker than covalent ones and do not lead to a significant restructuring of the electronic structure of the interacting particles. (This is only partially true. For example, all enzymatic and catalytic reactions begin with a weak intermolecular interaction between a substrate and an enzyme or a molecule with a catalyst, but several such weak interactions with the required spatial configuration of the active center of the enzyme lead to significant restructuring in the energy states of molecules or substrates, all of which ultimately leads to the breaking of some and the formation of other covalent chemical bonds. Strictly speaking, all enzymatic reactions begin with intermolecular interactions between the substrate and the enzyme, therefore the importance of these interactions is especially great in biochemistry and molecular biology, and is the basis of enzymology).');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Hydrogen bonding', 'A hydrogen bond refers to the attraction between a hydrogen atom that is covalently bonded to an element with high electronegativity, usually nitrogen, oxygen, or fluorine, and another highly electronegative atom. The hydrogen bond is often described as a strong electrostatic interaction. However, it also has some features of covalent bonding: it is directional, stronger than a van der Waals force interaction, produces interatomic distances shorter than the sum of their van der Waals radii, and usually involves a limited number of interaction partners, which can be interpreted as a kind of valence. The number of hydrogen bonds formed between molecules is equal to the number of active pairs. The molecule which donates its hydrogen is termed the donor molecule, while the molecule containing lone pair participating in H bonding is termed the acceptor molecule. The number of active pairs is equal to the common number between number of hydrogens the donor has and the number of lone pairs the acceptor has.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'A hydrogen bond refers to the attraction between a hydrogen atom that is covalently bonded to an element with high electronegativity, usually nitrogen, oxygen, or fluorine, and another highly electronegative atom. The hydrogen bond is often described as a strong electrostatic interaction. However, it also has some features of covalent bonding: it is directional, stronger than a van der Waals force interaction, produces interatomic distances shorter than the sum of their van der Waals radii, and usually involves a limited number of interaction partners, which can be interpreted as a kind of valence. The number of hydrogen bonds formed between molecules is equal to the number of active pairs. The molecule which donates its hydrogen is termed the donor molecule, while the molecule containing lone pair participating in H bonding is termed the acceptor molecule. The number of active pairs is equal to the common number between number of hydrogens the donor has and the number of lone pairs the acceptor has.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Hydrogen bonding', 'Though both are not depicted in the diagram, water molecules have four active bonds. The oxygen atom’s two lone pairs interact with a hydrogen each, forming two additional hydrogen bonds, and the second hydrogen atom also interacts with a neighbouring oxygen. Intermolecular hydrogen bonding is responsible for the high boiling point of water (100 °C) compared to the other group 16 hydrides, which have little capability to hydrogen bond. Intramolecular hydrogen bonding is partly responsible for the secondary, tertiary, and quaternary structures of proteins and nucleic acids. It also plays an important role in the structure of polymers, both synthetic and natural.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Though both are not depicted in the diagram, water molecules have four active bonds. The oxygen atom’s two lone pairs interact with a hydrogen each, forming two additional hydrogen bonds, and the second hydrogen atom also interacts with a neighbouring oxygen. Intermolecular hydrogen bonding is responsible for the high boiling point of water (100 °C) compared to the other group 16 hydrides, which have little capability to hydrogen bond. Intramolecular hydrogen bonding is partly responsible for the secondary, tertiary, and quaternary structures of proteins and nucleic acids. It also plays an important role in the structure of polymers, both synthetic and natural.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Salt bridge', 'The attraction between cationic and anionic sites is a noncovalent, or intermolecular interaction which is usually referred to as ion pairing or salt bridge. It is essentially due to electrostatic forces, although in aqueous medium the association is driven by entropy and often even endothermic. Most salts form crystals with characteristic distances between the ions; in contrast to many other noncovalent interactions, salt bridges are not directional and show in the solid state usually contact determined only by the van der Waals radii of the ions. Inorganic as well as organic ions display in water at moderate ionic strength I similar salt bridge as association ΔG values around 5 to 6 kJ/mol for a 1:1 combination of anion and cation, almost independent of the nature (size, polarizability, etc.) of the ions. The ΔG values are additive and approximately a linear function of the charges, the interaction of e.g. a doubly charged phosphate anion with a single charged ammonium cation accounts for about 2x5 = 10 kJ/mol. The ΔG values depend on the ionic strength I of the solution, as described by the Debye-Hückel equation, at zero ionic strength one observes ΔG = 8 kJ/mol.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'The attraction between cationic and anionic sites is a noncovalent, or intermolecular interaction which is usually referred to as ion pairing or salt bridge. It is essentially due to electrostatic forces, although in aqueous medium the association is driven by entropy and often even endothermic. Most salts form crystals with characteristic distances between the ions; in contrast to many other noncovalent interactions, salt bridges are not directional and show in the solid state usually contact determined only by the van der Waals radii of the ions. Inorganic as well as organic ions display in water at moderate ionic strength I similar salt bridge as association ΔG values around 5 to 6 kJ/mol for a 1:1 combination of anion and cation, almost independent of the nature (size, polarizability, etc.) of the ions. The ΔG values are additive and approximately a linear function of the charges, the interaction of e.g. a doubly charged phosphate anion with a single charged ammonium cation accounts for about 2x5 = 10 kJ/mol. The ΔG values depend on the ionic strength I of the solution, as described by the Debye-Hückel equation, at zero ionic strength one observes ΔG = 8 kJ/mol.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Dipole–dipole and similar interactions', 'Dipole–dipole interactions (or Keesom interactions) are electrostatic interactions between molecules which have permanent dipoles. This interaction is stronger than the London forces but is weaker than ion-ion interaction because only partial charges are involved. These interactions tend to align the molecules to increase attraction (reducing potential energy). An example of a dipole–dipole interaction can be seen in hydrogen chloride (HCl): the positive end of a polar molecule will attract the negative end of the other molecule and influence its position. Polar molecules have a net attraction between them. Examples of polar molecules include hydrogen chloride (HCl) and chloroform (CHCl3). Often molecules contain dipolar groups of atoms, but have no overall dipole moment on the molecule as a whole. This occurs if there is symmetry within the molecule that causes the dipoles to cancel each other out. This occurs in molecules such as tetrachloromethane and carbon dioxide. The dipole–dipole interaction between two individual atoms is usually zero, since atoms rarely carry a permanent dipole. The Keesom interaction is a van der Waals force. It is discussed further in the section "Van der Waals forces".', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Dipole–dipole interactions (or Keesom interactions) are electrostatic interactions between molecules which have permanent dipoles. This interaction is stronger than the London forces but is weaker than ion-ion interaction because only partial charges are involved. These interactions tend to align the molecules to increase attraction (reducing potential energy). An example of a dipole–dipole interaction can be seen in hydrogen chloride (HCl): the positive end of a polar molecule will attract the negative end of the other molecule and influence its position. Polar molecules have a net attraction between them. Examples of polar molecules include hydrogen chloride (HCl) and chloroform (CHCl3). Often molecules contain dipolar groups of atoms, but have no overall dipole moment on the molecule as a whole. This occurs if there is symmetry within the molecule that causes the dipoles to cancel each other out. This occurs in molecules such as tetrachloromethane and carbon dioxide. The dipole–dipole interaction between two individual atoms is usually zero, since atoms rarely carry a permanent dipole. The Keesom interaction is a van der Waals force. It is discussed further in the section "Van der Waals forces".');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Ion–dipole and ion–induced dipole forces', 'Ion–dipole and ion–induced dipole forces are similar to dipole–dipole and dipole–induced dipole interactions but involve ions, instead of only polar and non-polar molecules. Ion–dipole and ion–induced dipole forces are stronger than dipole–dipole interactions because the charge of any ion is much greater than the charge of a dipole moment. Ion–dipole bonding is stronger than hydrogen bonding. An ion–dipole force consists of an ion and a polar molecule interacting. They align so that the positive and negative groups are next to one another, allowing maximum attraction. An important example of this interaction is hydration of ions in water which give rise to hydration enthalpy. The polar water molecules surround themselves around ions in water and the energy released during the process is known as hydration enthalpy. The interaction has its immense importance in justifying the stability of various ions (like Cu2+) in water. An ion–induced dipole force consists of an ion and a non-polar molecule interacting. Like a dipole–induced dipole force, the charge of the ion causes distortion of the electron cloud on the non-polar molecule.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
where not exists (select 1 from public.content_chunks where topic_id = 'bonding-periodic' and body = 'Ion–dipole and ion–induced dipole forces are similar to dipole–dipole and dipole–induced dipole interactions but involve ions, instead of only polar and non-polar molecules. Ion–dipole and ion–induced dipole forces are stronger than dipole–dipole interactions because the charge of any ion is much greater than the charge of a dipole moment. Ion–dipole bonding is stronger than hydrogen bonding. An ion–dipole force consists of an ion and a polar molecule interacting. They align so that the positive and negative groups are next to one another, allowing maximum attraction. An important example of this interaction is hydration of ions in water which give rise to hydration enthalpy. The polar water molecules surround themselves around ions in water and the energy released during the process is known as hydration enthalpy. The interaction has its immense importance in justifying the stability of various ions (like Cu2+) in water. An ion–induced dipole force consists of an ion and a non-polar molecule interacting. Like a dipole–induced dipole force, the charge of the ion causes distortion of the electron cloud on the non-polar molecule.');
insert into public.content_chunks (topic_id, title, body, source_name, source_url, license)
select 'bonding-periodic', 'Intermolecular force: Van der Waals forces', 'The van der Waals forces arise from interaction between uncharged atoms or molecules, leading not only to such phenomena as the cohesion of condensed phases and physical absorption of gases, but also to a universal force of attraction between macroscopic bodies.', 'Wikipedia: Intermolecular force', 'https://en.wikipedia.org/w/index.php?title=Intermolecular_force&oldid=1366432922', 'CC BY-SA 4.0. Wikipedia contributors (see page history). Excerpted and split into passages.'
